    silver_glassannealingfork = { name = "Srebrn vilice za ohlajanje stekla", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn vilice za ohlajanje stekla za steklarje." },
    gilded_glassannealingfork = { name = "Pozlačen vilice za ohlajanje stekla", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen vilice za ohlajanje stekla za steklarje." },
