    sovereign_glassannealingfork_palace = { name = "Suverena glassannealingfork palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GlassAnnealingForkMaker.ironStock=18; GlassAnnealingForkMaker.bronzeStock=14; GlassAnnealingForkMaker.woodStock=10; GlassAnnealingForkMaker.leatherStock=8; GlassAnnealingForkMaker.silverStock=8; GlassAnnealingForkMaker.goldStock=6; GlassAnnealingForkMaker.jewelStock=4; GlassAnnealingForkMaker.pearlStock=4
GlassAnnealingForkMaker.productStock = {}; GlassAnnealingForkMaker.buildings = {}; GlassAnnealingForkMaker.maker = nil; GlassAnnealingForkMaker.activeMaking = {}; GlassAnnealingForkMaker.totalProducts = 0; GlassAnnealingForkMaker.dayTimer = 0
function GlassAnnealingForkMaker.init() GlassAnnealingForkMaker.ironStock=18; GlassAnnealingForkMaker.bronzeStock=14; GlassAnnealingForkMaker.woodStock=10; GlassAnnealingForkMaker.leatherStock=8; GlassAnnealingForkMaker.silverStock=8; GlassAnnealingForkMaker.goldStock=6; GlassAnnealingForkMaker.jewelStock=4; GlassAnnealingForkMaker.pearlStock=4; GlassAnnealingForkMaker.productStock={}; GlassAnnealingForkMaker.buildings={}; GlassAnnealingForkMaker.maker=nil; GlassAnnealingForkMaker.activeMaking={}; GlassAnnealingForkMaker.totalProducts=0; GlassAnnealingForkMaker.dayTimer=0; print("[GlassAnnealingForkMaker] Royal Glass Annealing Fork Maker System initialized (6 products, 4 buildings)") end
function GlassAnnealingForkMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassAnnealingForkMaker.maker={name=n or ("Viliar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Viliar najet: %s (spretnost: %d)",GlassAnnealingForkMaker.maker.name,s),"success") end; return true end
function GlassAnnealingForkMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassAnnealingForkMaker.build(id) local ok,e=GlassAnnealingForkMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassAnnealingForkMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassAnnealingForkMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassAnnealingForkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassAnnealingForkMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassAnnealingForkMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassAnnealingForkMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassAnnealingForkMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassAnnealingForkMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassAnnealingForkMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassAnnealingForkMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassAnnealingForkMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassAnnealingForkMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassAnnealingForkMaker.buildings==0 then return false,"Potrebna vilična delavnica" end; if not GlassAnnealingForkMaker.maker then return false,"Potreben viliar" end; return true end
function GlassAnnealingForkMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassAnnealingForkMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassAnnealingForkMaker.ironStock=GlassAnnealingForkMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassAnnealingForkMaker.bronzeStock=GlassAnnealingForkMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassAnnealingForkMaker.woodStock=GlassAnnealingForkMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassAnnealingForkMaker.leatherStock=GlassAnnealingForkMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassAnnealingForkMaker.silverStock=GlassAnnealingForkMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassAnnealingForkMaker.goldStock=GlassAnnealingForkMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassAnnealingForkMaker.jewelStock=GlassAnnealingForkMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassAnnealingForkMaker.pearlStock=GlassAnnealingForkMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassAnnealingForkMaker.maker then t=math.max(1,t-math.floor(GlassAnnealingForkMaker.maker.skill/13)) end; table.insert(GlassAnnealingForkMaker.activeMaking,{id="glassannealingfork_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassAnnealingForkMaker.completeMaking(m) local q=1.0+(GlassAnnealingForkMaker.getQualityBonus()/100); if GlassAnnealingForkMaker.maker then q=q+(GlassAnnealingForkMaker.maker.skill/140) end; q=math.min(2.5,q); GlassAnnealingForkMaker.productStock[m.productType]=(GlassAnnealingForkMaker.productStock[m.productType] or 0)+m.quantity; GlassAnnealingForkMaker.totalProducts=GlassAnnealingForkMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassAnnealingForkMaker.maker then GlassAnnealingForkMaker.maker.itemsMade=GlassAnnealingForkMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassAnnealingForkMaker.maker.skill=math.min(100,GlassAnnealingForkMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vilice izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassannealingfork.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassAnnealingForkMaker.update(dt) if not _G.state then return end; GlassAnnealingForkMaker.dayTimer=GlassAnnealingForkMaker.dayTimer+dt; if GlassAnnealingForkMaker.dayTimer>=30 then GlassAnnealingForkMaker.dayTimer=0; for i=#GlassAnnealingForkMaker.activeMaking,1,-1 do local m=GlassAnnealingForkMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassAnnealingForkMaker.completeMaking(m); table.remove(GlassAnnealingForkMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassAnnealingForkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassAnnealingForkMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassAnnealingForkMaker.getStats() return {ironStock=GlassAnnealingForkMaker.ironStock,bronzeStock=GlassAnnealingForkMaker.bronzeStock,woodStock=GlassAnnealingForkMaker.woodStock,leatherStock=GlassAnnealingForkMaker.leatherStock,silverStock=GlassAnnealingForkMaker.silverStock,goldStock=GlassAnnealingForkMaker.goldStock,jewelStock=GlassAnnealingForkMaker.jewelStock,pearlStock=GlassAnnealingForkMaker.pearlStock,productStock=GlassAnnealingForkMaker.productStock,numBuildings=#GlassAnnealingForkMaker.buildings,hasMaker=GlassAnnealingForkMaker.maker~=nil,makerName=GlassAnnealingForkMaker.maker and GlassAnnealingForkMaker.maker.name or "—",makerSkill=GlassAnnealingForkMaker.maker and GlassAnnealingForkMaker.maker.skill or 0,activeMaking=#GlassAnnealingForkMaker.activeMaking,totalProducts=GlassAnnealingForkMaker.totalProducts} end
return GlassAnnealingForkMaker
